function extractFromChoices(choices) {
  if (!Array.isArray(choices)) {
    return "";
  }

  const chunks = [];
  for (const choice of choices) {
    const text = extractContent(choice?.message?.content ?? choice?.text);
    if (text) {
      chunks.push(text);
    }
  }

  return chunks.join("\n").trim();
}

