  if (typeof content === "string") {
    return content.trim();
  }

  if (!Array.isArray(content)) {
    return "";
  }

  const chunks = [];
  for (const part of content) {
    if (typeof part === "string") {
      chunks.push(part);
      continue;
    }

    const text = part?.text ?? part?.output_text;
    if (typeof text === "string" && text.trim()) {
      chunks.push(text.trim());
    }
